const CACHE='tankrush-v7';
const ASSETS=['./','./index.html','./style.css?v=7','./manifest.webmanifest','./icons/icon-192.png','./icons/icon-512.png','./src/main.js?v=7','./src/input.js?v=7','./src/simulation.js?v=7','./src/scene.js?v=7','./src/models.js?v=7','./src/assets.js?v=7','./vendor/three/three.module.js','./vendor/three/three.core.js','./vendor/three/addons/loaders/GLTFLoader.js','./vendor/three/addons/utils/BufferGeometryUtils.js','./models/submarine.glb','./models/buggy.glb','./models/guppy.glb','./models/piranha.glb','./models/spider.glb','./models/snake.glb','./models/monitor.glb','./models/chameleon.glb','./src/habitats.js?v=7','./src/decor.js?v=7','./src/creatures.js?v=7','./models/tetra.glb','./models/discus.glb','./models/rasbora.glb','./models/gourami.glb','./models/cichlid.glb','./models/clownfish.glb','./models/tang.glb','./models/shrimp.glb','./models/jellyfish.glb','./models/bearded.glb','./models/skink.glb','./models/gecko.glb','./models/crested.glb','./models/frog.glb','./models/scorpion.glb'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('tankrush-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(event.request.mode==='navigate'){try{const res=await fetch(event.request);if(res.ok)cache.put(event.request,res.clone());return res;}catch{return await cache.match(event.request)||await cache.match('./index.html');}}return await cache.match(event.request)||fetch(event.request).then(res=>{if(res.ok)cache.put(event.request,res.clone());return res;});})());});
